package com.primehr.migration;import org.flywaydb.core.Flyway;import org.flywaydb.core.api.MigrationVersion;import org.junit.jupiter.api.Test;import java.sql.*;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;
class PrimeHrV34ToV35UpgradeTest{@Test void populatedCalibrationFoundationSurvivesAppealMigration()throws Exception{String db="primehr_v35_"+UUID.randomUUID().toString().replace("-","");String url="jdbc:h2:mem:"+db+";MODE=PostgreSQL;DB_CLOSE_DELAY=-1";Map<String,String> placeholders=Map.of("primehrSchema","PUBLIC");Flyway initial=Flyway.configure().dataSource(url,"sa","").locations("classpath:db/migration/postgresql").schemas("PUBLIC").defaultSchema("PUBLIC").placeholders(placeholders).target(MigrationVersion.fromVersion("34")).cleanDisabled(false).load();initial.migrate();String id=UUID.randomUUID().toString();try(var c=DriverManager.getConnection(url,"sa","");var s=c.createStatement()){s.executeUpdate("INSERT INTO PUBLIC.spms_objective (id,agency_id,code,normalized_code,record_version,created_by,created_at,updated_by,updated_at) VALUES ('"+id+"','UPGRADE-35','OBJ','OBJ',0,'test',CURRENT_TIMESTAMP,'test',CURRENT_TIMESTAMP)");}try{Flyway upgraded=Flyway.configure().dataSource(url,"sa","").locations("classpath:db/migration/postgresql").schemas("PUBLIC").defaultSchema("PUBLIC").placeholders(placeholders).target(MigrationVersion.fromVersion("35")).cleanDisabled(false).load();upgraded.migrate();assertThat(upgraded.info().current().getVersion().getVersion()).isEqualTo("35");try(var c=DriverManager.getConnection(url,"sa","");var result=c.createStatement().executeQuery("SELECT COUNT(*) FROM PUBLIC.spms_objective WHERE id='"+id+"'")){result.next();assertThat(result.getLong(1)).isOne();for(String table:List.of("spms_rating_acknowledgment","spms_rating_appeal","spms_rating_appeal_evidence","spms_intervention_rule","spms_performance_intervention","spms_intervention_checkpoint")){try(var empty=c.createStatement().executeQuery("SELECT COUNT(*) FROM PUBLIC."+table)){empty.next();assertThat(empty.getLong(1)).isZero();}}}}finally{initial.clean();}}}
